CREATE TYPE "SubscriptionStatus" AS ENUM ('ACTIVE','SUSPENDED');
CREATE TABLE "Plan" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"limits" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Plan_pkey" PRIMARY KEY("id"),CONSTRAINT "Plan_code_key" UNIQUE("code"));
CREATE TABLE "Subscription" ("id" UUID NOT NULL,"companyId" UUID NOT NULL,"planId" UUID NOT NULL,"status" "SubscriptionStatus" NOT NULL DEFAULT 'ACTIVE',"suspendedAt" TIMESTAMPTZ(6),"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Subscription_pkey" PRIMARY KEY("id"),CONSTRAINT "Subscription_companyId_key" UNIQUE("companyId"));
CREATE INDEX "Subscription_planId_idx" ON "Subscription"("planId"); ALTER TABLE "Subscription" ADD CONSTRAINT "Subscription_companyId_fkey" FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "Subscription" ADD CONSTRAINT "Subscription_planId_fkey" FOREIGN KEY("planId") REFERENCES "Plan"("id") ON DELETE RESTRICT;
ALTER TABLE "Subscription" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Subscription" FORCE ROW LEVEL SECURITY; CREATE POLICY "subscription_tenant" ON "Subscription" FOR ALL USING("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid);
